mod app;
mod doc;
mod i18n;
mod i18n_data;

use std::path::PathBuf;

use eframe::egui;

// Subset of Noto Sans CJK covering every UI string (390 glyphs, ~180 KB).
// Generated by scripts/gen-fonts.py from the shared i18n dictionaries.
static CJK_TC: &[u8] = include_bytes!("../assets/NotoSansCJKtc-subset.otf");
static CJK_SC: &[u8] = include_bytes!("../assets/NotoSansCJKsc-subset.otf");

fn install_fonts(ctx: &egui::Context, locale: i18n::Locale) {
    let bytes: &'static [u8] = match locale {
        i18n::Locale::ZhHans => CJK_SC,
        _ => CJK_TC,
    };
    let mut fonts = egui::FontDefinitions::default();
    fonts.font_data.insert(
        "cjk".to_owned(),
        std::sync::Arc::new(egui::FontData::from_static(bytes)),
    );
    for family in [egui::FontFamily::Proportional, egui::FontFamily::Monospace] {
        fonts.families.entry(family).or_default().push("cjk".to_owned());
    }
    ctx.set_fonts(fonts);
}

fn main() -> eframe::Result<()> {
    let initial: Option<PathBuf> = std::env::args().nth(1).map(PathBuf::from);
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1280.0, 820.0])
            .with_min_inner_size([880.0, 560.0])
            .with_title("Lumen"),
        renderer: eframe::Renderer::Wgpu,
        ..Default::default()
    };
    eframe::run_native(
        "Lumen",
        options,
        Box::new(move |cc| {
            let locale = i18n::Locale::detect();
            install_fonts(&cc.egui_ctx, locale);
            Ok(Box::new(app::LumenApp::new(initial.clone())))
        }),
    )
}
